def binary_search(xs, target):
    left, right = 0, len(xs) - 1

    while left <= right:
        mid = (left + right) // 2
        if xs[mid] == target:
            return mid
        elif xs[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1
